const request = $input.first().json.body;

if (!request || typeof request !== 'object') {
  throw new Error('Request body is missing.');
}

if (!Array.isArray(request.ingredients) || request.ingredients.length < 1) {
  throw new Error('At least one ingredient is required.');
}

for (const ingredient of request.ingredients) {
  if (
    typeof ingredient.name !== 'string' ||
    ingredient.name.trim().length === 0
  ) {
    throw new Error('Every ingredient requires a name.');
  }

  if (
    typeof ingredient.amount !== 'number' ||
    !Number.isFinite(ingredient.amount) ||
    ingredient.amount <= 0
  ) {
    throw new Error(
      `Invalid amount for ingredient "${ingredient.name}".`
    );
  }

  if (
    typeof ingredient.unit !== 'string' ||
    ingredient.unit.trim().length === 0
  ) {
    throw new Error(
      `A unit is required for ingredient "${ingredient.name}".`
    );
  }
}

if (
  !Number.isInteger(request.portionCount) ||
  request.portionCount < 1 ||
  request.portionCount > 12
) {
  throw new Error('portionCount must be between 1 and 12.');
}

if (
  !Number.isInteger(request.cookCount) ||
  request.cookCount < 1 ||
  request.cookCount > 3
) {
  throw new Error('cookCount must be between 1 and 3.');
}

const allowedCookingTimes = ['quick', 'medium', 'complex'];
const allowedCuisines = [
  'german',
  'italian',
  'indian',
  'japanese',
  'gourmet',
  'fusion',
];
const allowedDiets = [
  'vegetarian',
  'vegan',
  'keto',
  'no-preference',
];

if (!allowedCookingTimes.includes(request.cookingTime)) {
  throw new Error('Invalid cookingTime.');
}

if (!allowedCuisines.includes(request.cuisine)) {
  throw new Error('Invalid cuisine.');
}

if (!allowedDiets.includes(request.diet)) {
  throw new Error('Invalid diet.');
}

return [
  {
    json: {
      request,
      validated: true,
    },
  },
];
